export const ALL_DISTRICT_VILLAGES = BIDKIN_VILLAGES;

/**
 * Filter villages by selected taluka (handles Marathi name, English name, or taluka ID)
 */
export function getVillagesByTaluka(talukaQuery: string): VillageInfo[] {
  if (!talukaQuery || !talukaQuery.trim()) {
    return BIDKIN_VILLAGES;
  }
  const q = talukaQuery.trim().toLowerCase();

  // If specific taluka matching
  const filtered = BIDKIN_VILLAGES.filter(v => {
    return (
      v.taluka_mr.toLowerCase() === q ||
      v.taluka_en.toLowerCase() === q ||
      v.taluka_mr.toLowerCase().includes(q) ||
      v.taluka_en.toLowerCase().includes(q)
    );
  });

  if (filtered.length > 0) {
    return filtered;
  }

  // Fallback for ID matching (e.g. 'csn' or 'csn_city' -> Chhatrapati Sambhajinagar)
  if (q.includes('csn') || q.includes('sambhaji') || q.includes('aurangabad')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr.includes('संभाजीनगर') || v.taluka_en.includes('Sambhajinagar'));
  }
  if (q.includes('paithan') || q.includes('पैठण')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'पैठण' || v.taluka_en === 'Paithan');
  }
  if (q.includes('gangapur') || q.includes('गंगापूर')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'गंगापूर' || v.taluka_en === 'Gangapur');
  }
  if (q.includes('vaijapur') || q.includes('वैजापूर')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'वैजापूर' || v.taluka_en === 'Vaijapur');
  }
  if (q.includes('kannad') || q.includes('कन्नड')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'कन्नड' || v.taluka_en === 'Kannad');
  }
  if (q.includes('khuldabad') || q.includes('खुल्दाबाद')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'खुल्दाबाद' || v.taluka_en === 'Khuldabad');
  }
  if (q.includes('sillod') || q.includes('सिल्लोड')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'सिल्लोड' || v.taluka_en === 'Sillod');
  }
  if (q.includes('soegaon') || q.includes('सोयगाव')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'सोयगाव' || v.taluka_en === 'Soegaon');
  }
  if (q.includes('phulambri') || q.includes('फुलंब्री')) {
    return BIDKIN_VILLAGES.filter(v => v.taluka_mr === 'फुलंब्री' || v.taluka_en === 'Phulambri');
  }

  return BIDKIN_VILLAGES;
}

/**
 * Returns taluka metadata matching a given name or ID
 */
export function getTalukaObject(talukaQuery: string): TalukaInfo | undefined {
  if (!talukaQuery) return undefined;
  const q = talukaQuery.trim().toLowerCase();
  return TALUKAS.find(t => 
    t.id.toLowerCase() === q ||
    t.name_mr.toLowerCase() === q ||
    t.name_en.toLowerCase() === q ||
    t.name_mr.toLowerCase().includes(q) ||
    t.name_en.toLowerCase().includes(q)
  );
}
